  1138  static ssize_t dns_label_decode(uint8_t const *buf, uint8_t const **start, uint8_t const **next)
  1139  {
  1140          uint8_t const *p;
  1141
  1142          p = *start;
  1143
  1144          if (*p == 0x00) {
  1145                  *next = p + 1;
  1146                  return 0;
  1147          }
  1148
  1149          /*
  1150           *      Pointer, which MUST point to a valid label, but we don't
  1151           *      check.
  1152           */
  1153          if (*p > 63) {
  1154                  uint16_t offset;
  1155
  1156                  offset = p[1];
  1157                  offset += ((*p & ~0xc0) << 8);
  1158
  1159                  p = buf + offset;
  1160          }
  1161
  1162          /*
  1163           *      Tell the caller where the actual label is located.
  1164           */
  1165          *start = p;
  1166          *next = p + *p + 1;
  1167          return *p;
  1168  }
