  1171  /** Decode a #fr_value_box_t from one DNS label
  1172   *
  1173   * The output type is always FR_TYPE_STRING
  1174   *
  1175   * Note that the caller MUST call fr_dns_labels_network_verify(src, len, start)
  1176   * before calling this function.  Otherwise bad things will happen.
  1177   *
  1178   * @param[in] ctx       Where to allocate any talloc buffers required.
  1179   * @param[out] dst      value_box to write the result to.
  1180   * @param[in] src       Start of the buffer containing DNS labels
  1181   * @param[in] len       Length of the buffer to decode
  1182   * @param[in] label     This particular label
  1183   * @param[in] tainted   Whether the value came from a trusted source.
  1184   * @param[in] lb        label tracking data structure
  1185   * @return
  1186   *      - >= 0 The number of network bytes consumed.
  1187   *      - <0 on error.
  1188   */
  1189  ssize_t fr_dns_label_to_value_box(TALLOC_CTX *ctx, fr_value_box_t *dst,
  1190                                    uint8_t const *src, size_t len, uint8_t const *label,
  1191                                    bool tainted, fr_dns_labels_t *lb)
  1192  {
  1193          ssize_t slen;
  1194          uint8_t const *after = label;
  1195          uint8_t const *current, *next;
  1196          uint8_t const *packet = src;
  1197          uint8_t *p;
  1198          char *q;
  1199
  1200          if (lb) packet = lb->start;
  1201
  1202          /*
  1203           *      Get the uncompressed length of the label, and the
  1204           *      label after this one.
  1205           */
  1206          slen = fr_dns_label_uncompressed_length(packet, src, len, &after, lb);
  1207          if (slen <= 0) {
  1208                  FR_PROTO_TRACE("dns_label_to_value_box - Failed getting length");
  1209                  return slen;
  1210          }
  1211
  1212          fr_value_box_init_null(dst);
  1213
  1214          /*
  1215           *      An empty label is a 0x00 byte.  Just create an empty
  1216           *      string.
  1217           */
  1218          if (slen == 1) {
  1219                  if (fr_value_box_bstr_alloc(ctx, &q, dst, NULL, 1, tainted) < 0) return -1;
  1220                  q[0] = '.';
  1221                  return after - label;
  1222          }
  1223
  1224          /*
  1225           *      Allocate the string and set up the value_box
  1226           */
  1227          if (fr_value_box_bstr_alloc(ctx, &q, dst, NULL, slen, tainted) < 0) return -1;
  1228
  1229          current = label;
  1230          p = (uint8_t *) q;
  1231          q += slen;
  1232
  1233          while ((current < after) && (*current != 0x00)) {
  1234                  /*
  1235                   *      Get how many bytes this label has, and where
  1236                   *      we will go to obtain the next label.
  1237                   *
  1238                   *      Note that slen > 0 here, as dns_label_decode()
  1239                   *      only returns 0 when the current byte is 0x00,
  1240                   *      which it can't be.
  1241                   */
  1242                  slen = dns_label_decode(packet, &current, &next);
  1243
  1244                  /*
  1245                   *      As a sanity check, ensure we don't have a
  1246                   *      buffer overflow.
  1247                   */
  1248                  if ((p + slen) > (uint8_t *) q) {
  1249                          FR_PROTO_TRACE("dns_label_to_value_box - length %zd Failed at %d", slen, __LINE__);
  1250
  1251                  fail:
  1252                          fr_value_box_clear(dst);
  1253                          return -1;
  1254                  }
  1255
  1256                  /*
  1257                   *      Add '.' before the label, but only for the
  1258                   *      second and subsequent labels.
  1259                   */
  1260                  if (p != (uint8_t const *) dst->vb_strvalue) {
  1261                          *(p++) = '.';
  1262                  }
  1263
  1264                  /*
  1265                   *      Copy the raw bytes from the network.
  1266                   */
  1267                  memcpy(p, current + 1, slen);
  1268
  1269                  /*
  1270                   *      Go ahead in the output string, and go to the
  1271                   *      next label for decoding.
  1272                   */
  1273                  p += slen;
  1274                  current = next;
  1275          }
  1276
  1277          /*
  1278           *      As a last sanity check, ensure that we've filled the
  1279           *      buffer exactly.
  1280           */
  1281          if (p != (uint8_t *) q) {
  1282                  FR_PROTO_TRACE("dns_label_to_value_box - Failed at %d", __LINE__);
  1283                  goto fail;
  1284          }
  1285
  1286          *p = '\0';
  1287
  1288          /*
  1289           *      Return the number of network bytes used to parse this
  1290           *      part of the label.
  1291           */
  1292          return after - label;
  1293  }
   334  static ssize_t decode_dns_labels(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_t const *dict,
   335                                   fr_dict_attr_t const *parent,
   336                                   uint8_t const *data, size_t const data_len, void *decode_ctx)
   337  {
   338          ssize_t slen;
   339          size_t total, labels_len;
   340          fr_pair_t *vp;
   341          uint8_t const *next = data;
   342          fr_dns_ctx_t *packet_ctx = decode_ctx;
   343
   344          FR_PROTO_HEX_DUMP(data, data_len, "decode_dns_labels");
   345
   346          /*
   347           *      This function handles both single-valued and array
   348           *      types.  It's just easier that way.
   349           */
   350          if (!parent->flags.array) {
   351                  /*
   352                   *      Decode starting at "NEXT", but allowing decodes from the start of the packet.
   353                   */
   354                  slen = fr_dns_label_uncompressed_length(packet_ctx->packet, data, data + data_len - packet_ctx->packet, &next, packet_ctx->lb);
   355                  if (slen <= 0) {
   356                          FR_PROTO_TRACE("length failed at %zd - %s", slen, fr_strerror());
   357                          goto raw;
   358                  }
   359
   360                  labels_len = next - data; /* decode only what we've found */
   361          } else {
   362                  /*
   363                   *      Get the length of the entire set of labels, up
   364                   *      to (and including) the final 0x00.
   365                   *
   366                   *      If any of the labels point outside of this
   367                   *      area, OR they are otherwise invalid, then that's an error.
   368                   */
   369                  slen = fr_dns_labels_network_verify(packet_ctx->packet, data, data + data_len - packet_ctx->packet, data, packet_ctx->lb);
   370                  if (slen < 0) {
   371                          FR_PROTO_TRACE("verify failed");
   372                  raw:
   373                          return decode_raw(ctx, cursor, dict, parent, data, data_len, decode_ctx);
   374                  }
   375
   376                  labels_len = slen;
   377          }
   378
   379          /*
   380           *      Loop over the input buffer, decoding the labels one by
   381           *      one.
   382           */
   383          for (total = 0; total < labels_len; total += slen) {
   384                  vp = fr_pair_afrom_da(ctx, parent);
   385                  if (!vp) return PAIR_DECODE_OOM;
   386
   387                  /*
   388                   *      Having verified the input above, this next
   389                   *      function should never fail unless there's a
   390                   *      bug in the code.
   391                   */
   392                  slen = fr_dns_label_to_value_box(vp, &vp->data, data, labels_len, data + total, true, packet_ctx->lb);
   393                  if (slen <= 0) {
   394                          FR_PROTO_TRACE("Failed decoding label at %zd", slen);
   395                          talloc_free(vp);
   396                          goto raw;
   397                  }
   398
   399                  vp->type = VT_DATA;
   400                  fr_dcursor_append(cursor, vp);
   401          }
   402
   403          FR_PROTO_TRACE("decode_dns_labels - %zu", labels_len);
   404          return labels_len;
   405  }
